"""Compose v9 from local production evidence and actual current product captures."""
import json,re,html
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
OUT=ROOT/'video/out'; OUT.mkdir(exist_ok=True)
rows=[]
for line in (ROOT/'docs/video_script.md').read_text().splitlines():
 if re.match(r'\| \d:\d\d–',line):
  time,screen,voice=[x.strip() for x in line.split('|')[1:4]]
  a,b=time.split('–'); seconds=lambda x:int(x.split(':')[0])*60+int(x.split(':')[1])
  rows.append(dict(start=seconds(a),duration=seconds(b)-seconds(a),voice=voice))
escape=html.escape
papers=[]
for name,paper,stamp in [('TSMixer','disc_2303_06053','20261009-201230'),('SparseTSF','disc_2405_00946','20261009-220822'),('GLinear','disc_2501_01087','20261010-161916')]:
 folder=ROOT/'web/public/data'/paper/stamp
 d=json.loads((folder/'dossier.json').read_text());ev=[json.loads(l) for l in (folder/'events.jsonl').read_text().splitlines() if l]
 v=d['verdicts'][0];c=d['claims'][0];end=next(x for x in ev if x['type']=='run_end')
 assert d['mode']=='nachbau_autorencode' and v['methode']=='nicht geprueft'
 final=d['attempts'][-1]['code_hash'];seed=[x for x in d['attempts'] if x['code_hash']==final and x.get('measured') is not None]
 papers.append(dict(name=name,claim=c['target'],mean=v['measured_mean'],std=v['measured_std'],cost=end['cost_gross_usd'],seeds=seed,events=ev,folder=str(folder.relative_to(ROOT))))
g=papers[-1]; failures=[x for x in g['events'] if x['type']=='repair']
bench=json.loads((ROOT/'web/public/data/benchmark.json').read_text());v4=next(v for v in bench['versions'] if v['id']=='v4');assert v4['summary']['placebo_reproduced']==0 and v4['summary']['placebo_total']==48

def img(name,title,kicker='Recorded product view · stored production run'):
 return f'<div class="kicker">{kicker}</div><h2>{title}</h2><div class="window"><img src="{name}.png"></div>'
def card(p):
 return f'''<div class="result"><div class="kicker">ETTh1 · Forecast horizon 96</div><h1>{p['name']}</h1><div class="scores"><div><label>Paper claims</label><strong>{p['claim']:.4f}</strong></div><span class="arrow">→</span><div><label>Nullius measured</label><strong>{p['mean']:.4f}</strong><small>± {p['std']:.4f} across 3 seeds</small></div></div><div class="pill">Target reached within ±0.01 MSE</div><p>Prediction error · lower is better</p><div class="warning">Selected after development · preliminary<br>Method fidelity not checked</div></div>'''
seedhtml=''.join(f'<div class="seed"><span>Seed {x["seed"]}</span><strong>{x["measured"]:.6f}</strong><small>{escape(x["branch_id"])}</small></div>' for x in g['seeds'])
errorhtml=''.join(f'<div class="error"><span>Candidate 2 · documented repair</span><code>{escape(x["error"].split("AttributeError:")[-1].split("(exit")[0].strip())}</code></div>' for x in failures)
shots=[
 '<div class="kicker">For researchers and ML teams</div><h1>Before you build on a paper,<br><i>can you reach its result?</i></h1><div class="flow"><span>Paper claim</span><b>→</b><span>Own experiment</span><b>→</b><span>Independent measurement</span></div><p class="motto">Here, the paper is the test suite.</p>',
 img('homepage','A finished check. Evidence you can follow.'),
 img('sources','Read the paper and the authors’ code.','Tavily · source provenance / Nemotron on Nebius Token Factory'),
 img('code','Nemotron writes its own experiment.','Super plans, writes & repairs · Lightning extracts targets / Authors’ program never executed'),
 f'<div class="kicker">GLinear · Recorded run · waiting time shortened</div><h2>Nebius Sandboxes run it.<br>Our checker measures it.</h2><div id="repair">{errorhtml}<p>Repairs belong to candidate 2, not the selected final program.</p></div><div id="seeds">{seedhtml}<p>Selected final code: 67dae24762de · Predictions scored by our harness</p></div>',
 ''.join(f'<div class="catalog-card" data-card="{i}">{card(p)}</div>' for i,p in enumerate(papers)),
 '<div class="kicker">Paper and authors’ code · separate evaluation</div><div class="counts"><div><strong>7/8</strong><h2>Development units</h2><p>Matched the reference verdict<br><b>In-sample</b></p></div><div><strong>0/1</strong><h2>RLinear held-out</h2><p>Matched the reference verdict<br>Separate check</p></div></div><div class="warning">Not a general success rate · method fidelity not checked</div>',
 img('whatif-before','Change the claim. The measurements stay.','What-if interaction · same stored GLinear predictions')+'<div id="control" class="control"><strong>0/48</strong><span>planted false targets confirmed<br>Benchmark v4 · earlier paper-only mode</span></div>',
 img('pdf','Take the evidence with you.','Actual certificate print preview · browser “Save as PDF / Print”'),
 f'<div class="kicker">GLinear · recorded inference receipt</div><div class="receipt"><h2>One check. A traceable result.</h2><hr><p><span>Claimed MSE</span><b>{g["claim"]:.4f}</b></p><p><span>Measured MSE</span><b>{g["mean"]:.4f} ± {g["std"]:.4f}</b></p><p><span>Seeds / fixed tolerance</span><b>3 / ±0.01</b></p><p><span>Gross inference cost</span><b>${g["cost"]:.4f}</b></p><hr><p class="warning">Tavily and sandbox costs separate.<br>Preliminary · method fidelity not checked.<br>Automatic source checks retain warnings.</p></div>',
 '<div class="kicker">Explore the recorded checks</div><h1><i>Nullius in verba.</i></h1><p class="motto">Take nobody’s word for it.</p><p class="repo">github.com/Script-hpp/Nullius</p><div class="partners">NVIDIA Nemotron · Nebius Token Factory & Sandboxes · Tavily</div>'
]
assert len(rows)==len(shots)
for i,row in enumerate(rows):row['content']=shots[i]
(OUT/'timeline.json').write_text(json.dumps(rows,indent=2))
fonts=ROOT/'web/node_modules'
import shutil
for file in [fonts/'@fontsource-variable/inter-tight/files/inter-tight-latin-wght-normal.woff2',fonts/'@fontsource/instrument-serif/files/instrument-serif-latin-400-italic.woff2']:
 shutil.copyfile(file,OUT/file.name)
css='''@font-face{font-family:Inter;src:url(inter-tight-latin-wght-normal.woff2)}@font-face{font-family:Serif;src:url(instrument-serif-latin-400-italic.woff2);font-style:italic}*{box-sizing:border-box}body{margin:0;background:#e9e4da;color:#252520;font-family:Inter}#stage{width:1280px;height:720px;position:absolute;transform-origin:0 0;overflow:hidden}.shot{position:absolute;inset:0;padding:58px 76px 115px;opacity:0;background:#f3f0e8;overflow:hidden}h1{font-size:70px;font-weight:550;letter-spacing:-3px;line-height:1.08;margin:65px 0 35px}h1 i{font-family:Serif;font-weight:400}h2{font-size:39px;letter-spacing:-1px;font-weight:550;margin:12px 0 24px}.kicker{font-size:19px;letter-spacing:1px;text-transform:uppercase;color:#65695c}.flow{display:flex;align-items:center;gap:20px;font-size:25px;margin-top:45px}.flow span{padding:14px 18px;border:1px solid #b9b7ac;border-radius:4px}.flow b{font-weight:400}.motto{font-family:Serif;font-style:italic;font-size:43px;margin:30px 0}.window{height:438px;overflow:hidden;border-radius:12px;border:1px solid #d0cdc3;box-shadow:0 12px 40px #29231118;transform-origin:50% 40%}.window img{width:100%;display:block}#shot2 .window img{transform:translateY(-170px)}#shot3 .window img{transform:translateY(-110px)}.scores{display:flex;gap:45px;align-items:center;margin:30px 0}.scores label{font-size:21px;display:block;color:#686b60}.scores strong{font-size:86px;font-weight:550;letter-spacing:-4px}.scores small{font-size:23px;display:block}.arrow{font-size:40px}.pill{display:inline-block;padding:12px 20px;border:1px solid #6e8168;background:#e0e8db;color:#41553b;border-radius:40px;font-size:24px}.warning{font-size:22px;line-height:1.4;color:#686253}.result h1{margin:32px 0 15px}.result p{font-size:22px}.catalog-card{position:absolute;inset:58px 76px}.counts{display:flex;gap:85px;margin-top:30px}.counts>div{width:45%}.counts strong{font-size:143px;font-weight:550;letter-spacing:-8px}.counts p{font-size:26px;line-height:1.5}.error{border-left:3px solid #a46e56;padding:14px 20px;background:#ece3d8;margin:12px 0}.error span{display:block;color:#876850;font-size:19px;margin-bottom:9px}.error code{font-size:21px;white-space:pre-wrap}.seed{display:grid;grid-template-columns:130px 180px 1fr;gap:12px;padding:24px 0;border-bottom:1px solid #c9c9bb;font-size:25px}.seed small{font-size:19px;font-family:monospace}.seed strong{font-weight:550}#repair p,#seeds p{font-size:19px;color:#62665c}#seeds{position:absolute;top:235px;width:1128px}.control{position:absolute;inset:245px 76px 115px;background:#f3f0e8;display:flex;align-items:center;gap:55px}.control strong{font-size:160px;letter-spacing:-8px}.control span{font-size:32px;line-height:1.5}.receipt{width:850px;margin:35px auto;background:#fcfbf7;padding:28px 40px;box-shadow:0 12px 35px #30251114}.receipt p{display:flex;justify-content:space-between;font-size:25px;margin:22px 0}.receipt p.warning{font-size:21px;display:block;line-height:1.55}.receipt h2{margin-top:0}.receipt hr{border:0;border-top:1px dashed #b7b4a7}.repo{font-size:38px}.partners{font-size:22px;color:#5d6456;margin-top:60px}#caption{position:absolute;bottom:24px;left:65px;right:65px;padding:15px 20px;background:#f3f0e8f5;font-size:26px;line-height:1.3;text-align:center;color:#34382d;border-top:1px solid #c4c6b7}#brand{position:absolute;top:20px;right:35px;font-size:18px;color:#757967}'''
(OUT/'film.html').write_text('<!doctype html><meta charset="utf-8"><style>'+css+'</style><div id="stage">'+''.join(f'<section class="shot" id="shot{i}">{s}</section>' for i,s in enumerate(shots))+'<div id="brand">nullius / v9</div><div id="caption"></div></div><script>const timeline='+json.dumps(rows)+''';
const captions=[['A paper’s claim becomes the acceptance criterion.'],['Recorded product view · stored production evidence'],['GLinear target checked manually before the run · automatic source check unverified'],['The agent writes its own experiment.'],['Actual recorded repairs → final seed measurements'],['Selected after development · preliminary · method fidelity not checked'],['Reference-verdict agreement · in-sample and held-out stay separate'],['Same measurements. A different claim.'],['Stored result, setup, sources and limitations in a portable certificate.'],['Inference cost only · preliminary result · warnings remain visible'],['Inspect a check before building on its paper.']];
window.seek=(sec)=>{const index=timeline.findIndex((s,i)=>sec>=s.start&&(i===timeline.length-1||sec<timeline[i+1].start));const s=timeline[index];const t=sec-s.start;document.querySelectorAll('.shot').forEach((el,i)=>{el.style.opacity=i===index?Math.min(1,t/.25):0});document.getElementById('caption').textContent=captions[index][0];document.querySelectorAll('.window').forEach(el=>el.style.transform=`scale(${1+Math.min(t/s.duration,1)*.025})`);if(index===4){document.getElementById('repair').style.opacity=t<6?1:0;document.getElementById('seeds').style.opacity=t<6?0:1;}if(index===5)document.querySelectorAll('.catalog-card').forEach((el,i)=>el.style.opacity=i===Math.min(2,Math.floor(t/6))?1:0);if(index===7){document.querySelector('#shot7 img').src=t<3?'whatif-before.png':'whatif-after.png';document.getElementById('control').style.opacity=t>=6?1:0;}};
function fit(){document.getElementById('stage').style.transform=`scale(${innerWidth/1280})`}fit();window.seek(0);
</script>''')
print('Composed',len(rows),'shots,',sum(r['duration'] for r in rows),'seconds from production evidence.')
